function mapSVG(hero=false){const id=hero?'hero':'explore';const coast=landPath();const markers=regions.map(r=>{const [x,y]=project(r.lon,r.lat);const active=r.id===state.a||r.id===state.b;const letter=r.id===state.a?'A':r.id===state.b?'B':'';return '<g class="map-marker" '+(!hero?'role="button" tabindex="0" aria-label="Select '+esc(r.name)+'" data-region="'+r.id+'"':'')+' transform="translate('+x+','+y+')">'+(active?'<circle class="pulse" r="22" fill="'+(r.id===state.a?'#e3bb84':'#c8e69b')+'"/><circle r="29" fill="none" stroke="'+(r.id===state.a?'#dbaf77':'#c2db94')+'" stroke-dasharray="3 4"/>':'')+'<circle class="core" r="'+(active?12:7)+'" fill="'+(r.id===state.a?'#d6aa6d':r.id===state.b?'#d5ecad':'#eef3d9')+'" stroke="#244f3f" stroke-width="2"/><text text-anchor="middle" style="font-size:10px;stroke:none" y="4">'+letter+'</text>'+(!hero?'<text x="16" y="-13">'+esc(r.name)+'</text>':'')+'</g>'}).join('');
let trees='';for(let i=0;i<80;i++){const x=500+Math.sin(i*7.1)*90,y=250+Math.cos(i*3.7)*75;trees+='<circle cx="'+x+'" cy="'+y+'" r="'+(8+i%9)+'" fill="'+['#31593c','#4c774b','#64875b','#7c995f'][i%4]+'" opacity=".62"/>'}let buildings='';for(let i=0;i<45;i++){const x=560+Math.sin(i*5.3)*135,y=405+Math.cos(i*3.7)*62;buildings+='<rect x="'+x+'" y="'+y+'" width="'+(6+i%9)+'" height="'+(10+i%20)+'" rx="2" fill="'+['#bcc7a1','#dae0bc','#93ac85'][i%3]+'" stroke="#648066" stroke-width="1"/>'}
return '<svg class="map-svg" viewBox="0 0 1140 700" role="img" aria-label="Singapore geographic outline with selected research locations'+(state.layer==='heat'&&!hero?' and authentic NASA MODIS imagery':' on an illustrated basemap')+'"><defs><linearGradient id="land-'+id+'" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#c6d4a3"/><stop offset=".45" stop-color="#8fa96d"/><stop offset="1" stop-color="#b1c48a"/></linearGradient><clipPath id="clip-'+id+'"><path d="'+coast+'"/></clipPath><pattern id="grid-'+id+'" width="90" height="90" patternUnits="userSpaceOnUse"><path d="M90 0H0V90" fill="none" stroke="'+(hero?'#82a48b':'#688b74')+'" stroke-opacity=".13"/></pattern></defs><rect width="1140" height="700" fill="url(#grid-'+id+')"/><g class="map-geography" style="transform-origin:570px 350px;transform:scale('+(hero?1:state.zoom)+')"><path d="'+coast+'" transform="translate(0,18)" fill="#41684f" opacity="'+(hero?'.8':'.2')+'"/><path class="map-coast" d="'+coast+'" fill="url(#land-'+id+')"/><g clip-path="url(#clip-'+id+')" class="illustration">'+trees+buildings+'<path d="M230 410 Q500 330 900 360 M470 90Q520 300 590 490 M320 180 Q630 200 800 450" fill="none" stroke="#e5e6b3" stroke-width="4" opacity=".35"/></g>'+(!hero&&state.layer==='heat'?'<image href="'+OFFLINE_IMAGES[frames[state.frame].date]+'" width="1140" height="700" clip-path="url(#clip-'+id+')" opacity=".95"/>':'')+markers+'</g></svg>'}
function options(){return Object.entries(V).map(([k,v])=>'<option value="'+k+'" '+(k===state.variable?'selected':'')+'>'+v.label+'</option>').join('')}
function route(){return location.hash.slice(1)||'home'}
function navigate(){if(typeof holoCleanup==='function')holoCleanup();if(timer){clearInterval(timer);timer=null}if(!ready)return;const r=route();$$('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+r));const pages={home:discoverHome,explore:explore,evidence:evidence,notebook:notebook,sources:sources};main.innerHTML=(pages[r]||discoverHome)();main.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});if(r==='evidence')bindChart();if(r==='home'||!pages[r])mountDiscover();{const scn=['evidence','notebook','sources'].includes(r)?3:2;labSound?.scene(scn,'Singapore')}}
function pageHeading(kicker,title,description,badge='NASA DATA · YOUR INVESTIGATION'){return '<div class="page-top"><div><div class="eyebrow">'+kicker+'</div><h1 class="page-title">'+title+'</h1><p>'+description+'</p></div><span class="pill">'+badge+'</span></div>'}
function previousHome(){return '<section class="hero"><div class="eyebrow">SINGAPORE · AN EARTH SYSTEM FIELD LAB</div><div class="hero-body"><div class="hero-copy"><h1>One island.<br><em>Many questions.</em></h1><p>Follow your curiosity across Singapore. Explore real NASA data, investigate the evidence, and tell the story in your own words.</p><div class="actions"><a class="button light" href="#explore">Explore the island <span>↗</span></a><a class="button ghost" href="#evidence">See the evidence <span>→</span></a></div></div><div class="hero-map">'+mapSVG(true)+'<div class="map-tooltip tip-b"><span class="dot b"></span> NATURAL LANDSCAPE<strong>Central Catchment</strong><small>A different place. A new question.</small></div><div class="map-tooltip tip-a"><span class="dot"></span> URBAN LANDSCAPE<strong>Downtown / CBD</strong><small>Explore surface heat patterns.</small></div><div class="coordinates">1.3521° N &nbsp; 103.8198° E<br>ILLUSTRATED GEOGRAPHIC BASEMAP</div></div></div><div class="hero-bottom"><span><b>25</b> complete years of regional data</span><span><b>05</b> environmental variables</span><span><b>06</b> authentic MODIS image dates</span><span class="mini"><span class="line-icon">◎</span> OBSERVE FIRST.<br>THEN ASK WHY.</span></div></section><section class="section"><div class="section-head"><div><div class="eyebrow">A LITTLE CURIOSITY GOES A LONG WAY</div><h2>What will you investigate?</h2></div><p>Start with a place, a pattern, or a question.<br>The evidence gets the final word.</p></div><div class="question-grid"><a href="#explore" class="question-card"><div class="card-art city"></div><span class="number">01 / SPATIAL EXPLORATION</span><h3>Does the city look warmer than the forest?</h3><p>Compare locations on real satellite imagery.<br>Numerical area extraction is a next step.</p><span class="card-arrow">↗</span></a><a href="#evidence" data-example="regional" class="question-card"><div class="card-art chart"></div><span class="number">02 / VERIFIED REGIONAL DATA</span><h3>How has Singapore changed over 25 years?</h3><p>Explore annual observations and reproducible trend evidence from NASA POWER.</p><span class="card-arrow">↗</span></a><a href="#explore" class="question-card"><div class="card-art forest"></div><span class="number">03 / DIFFERENT PERSPECTIVES</span><h3>What changes when you change the place?</h3><p>Choose two proposed study areas. Consider land cover, scale, and missing evidence.</p><span class="card-arrow">↗</span></a></div></section><section class="section manifesto"><div><div class="eyebrow">YOUR THINKING IS THE POINT</div><h2>More than a map.<br>A way to understand.</h2><p>ClimateLens helps you move from a first impression to a considered conclusion. The data provide evidence. You decide what it supports.</p><a href="#notebook" class="button ghost">Open my notebook →</a></div><div class="steps"><div class="step"><span>01</span><div><b>Ask & explore</b><span>Find a place. Make a prediction. Look closely.</span></div></div><div class="step"><span>02</span><div><b>Investigate the evidence</b><span>Separate observations, trends, and uncertainty.</span></div></div><div class="step"><span>03</span><div><b>Make it your own</b><span>Write, reflect, and take your investigation with you.</span></div></div></div></section>'}
function explore(){const a=region(state.a),b=region(state.b);return pageHeading('01 / LOCATE & OBSERVE','A small island. A closer look.','Choose locations, switch layers, and explore six historical satellite composites.')+'<section class="workbench"><aside class="sidebar"><p class="label">YOUR INVESTIGATION</p><h3>Choose your places</h3><p class="hint">Select an A/B slot, then a place on the map. Circles indicate proposed 1.5 km study areas; extraction is not yet connected.</p><button class="area-slot '+(state.slot==='a'?'selected':'')+'" data-slot="a"><span class="area-letter">A</span><b>'+esc(a.name)+'</b><small>'+esc(a.type)+'</small></button><button class="area-slot '+(state.slot==='b'?'selected':'')+'" data-slot="b"><span class="area-letter b">B</span><b>'+esc(b.name)+'</b><small>'+esc(b.type)+'</small></button><button class="button ghost" data-action="swap">Swap A & B ⇄</button><div class="separator"></div><label class="field"><span>Your question</span><textarea data-write="question" maxlength="2000">'+esc(state.question)+'</textarea></label><label class="field"><span>My prediction <small>· optional</small></span><textarea data-write="hypothesis" maxlength="2000" placeholder="I expect… because…">'+esc(state.hypothesis)+'</textarea></label><a class="button" href="#evidence">Explore available evidence ↗</a></aside><div class="map-panel"><div class="map-toolbar"><div class="segmented" aria-label="Map layer"><button data-layer="land" class="'+(state.layer==='land'?'active':'')+'">Illustrated map</button><button data-layer="heat" class="'+(state.layer==='heat'?'active':'')+'">MODIS surface temperature</button></div><a class="pill" href="#sources">NASA GIBS ↗</a></div><div class="map-canvas">'+mapSVG()+'<div class="map-status">'+(state.layer==='heat'?'<strong>Terra / MODIS · daytime · 8-day composite</strong><br>Transparent pixels have no valid displayed retrieval. Images are not region-average measurements.':'<strong>Choose a place to begin.</strong><br>Geographic outline with illustrative vegetation and buildings. Not a land-cover or elevation dataset.')+'</div><div class="north">N</div>'+(state.layer==='heat'?'<div class="map-legend"><img src="data/modis/legend.png" alt="Official NASA MODIS land surface temperature color scale"></div>':'')+'<div class="map-credit">Outline: Natural Earth / geo-countries · '+(state.layer==='heat'?'Imagery: NASA GIBS MODIS · historical snapshot':'Vegetation & buildings: illustration only')+'</div><div class="map-zoom"><button data-action="zoom-in" aria-label="Zoom in">+</button><button data-action="zoom-out" aria-label="Zoom out">−</button><button data-action="reset-map" aria-label="Reset map">⌖</button></div></div><div class="timeline"><button data-action="play" aria-label="Play historical imagery">▶</button><input id="frame" aria-label="Historical image date" type="range" min="0" max="5" value="'+state.frame+'"><strong id="frame-date">'+frames[state.frame].date+'</strong><small>6 sampled dates · 2024<br>8-day composites, not monthly means</small></div></div></section><div class="under-map"><div><b>Surface temperature ≠ air temperature</b><p>MODIS shows the land surface at satellite observation times. It does not measure the air temperature you feel.</p></div><div><b>One pixel has a footprint</b><p>1 km products cannot resolve individual streets or buildings. Choosing a marker does not create a finer measurement.</p></div><div><b>Missing is meaningful</b><p>Cloud and quality screening can leave gaps. No pixels are invented or interpolated in these displayed NASA images.</p></div></div>'}
function chart(result,expanded=false){const rows=result.annual,values=rows.map(r=>r.value);if(expanded)values.push(...result.stats.fitted);let lo=Math.min(...values),hi=Math.max(...values);const pad=(hi-lo||1)*.14;lo-=pad;hi+=pad;const x=i=>60+i/(rows.length-1)*650,y=v=>245-(v-lo)/(hi-lo)*200;let lines='';for(let i=0;i<5;i++){const v=lo+(hi-lo)*i/4;lines+='<line class="grid" x1="60" y1="'+y(v)+'" x2="710" y2="'+y(v)+'"/><text x="47" y="'+(y(v)+4)+'" text-anchor="end">'+fmt(v,hi-lo<3?1:0)+'</text>'}for(let i=0;i<rows.length;i+=6)lines+='<text x="'+x(i)+'" y="270" text-anchor="middle">'+rows[i].year+'</text>';const p=rows.map((r,i)=>x(i)+','+y(r.value)).join(' ');return '<svg class="chart" viewBox="0 0 750 290" role="img" aria-label="NASA POWER annual '+esc(V[state.variable].label)+' for Singapore 2001 to 2025"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#8eae72" stop-opacity=".25"/><stop offset="1" stop-color="#8eae72" stop-opacity="0"/></linearGradient></defs>'+lines+'<path d="M'+x(0)+',245 L'+p.split(' ').join(' L')+' L'+x(rows.length-1)+',245 Z" fill="url(#chart-fill)"/><polyline class="observed" points="'+p+'"/>'+(expanded?'<polyline class="fitted" points="'+result.stats.fitted.map((v,i)=>x(i)+','+y(v)).join(' ')+'"/>':'')+rows.map((r,i)=>'<circle class="point" tabindex="0" data-year="'+r.year+'" data-value="'+r.value+'" cx="'+x(i)+'" cy="'+y(r.value)+'" r="3.5" aria-label="'+r.year+': '+fmt(r.value)+' '+esc(V[state.variable].unit)+'"><title>'+r.year+': '+fmt(r.value)+' '+esc(V[state.variable].unit)+'</title></circle>').join('')+'</svg>'}
function evidence(){const r=current(),s=r.stats,v=V[state.variable];return pageHeading('02 / EXAMINE THE EVIDENCE','Look for a pattern. Then test it.','Authentic regional observations. Clear boundaries around what they can tell us.','NASA POWER · VIA CLIMATELENS SERVER')+'<section class="container"><div class="segmented" style="margin-bottom:20px"><button data-mode="regional" class="'+(state.mode==='regional'?'active':'')+'">Regional trend · available</button><button data-mode="spatial" class="'+(state.mode==='spatial'?'active':'')+'">A/B area comparison · planned</button></div>'+(state.mode==='spatial'?'<div class="notice"><strong>'+esc(region(state.a).name)+' vs '+esc(region(state.b).name)+': numerical comparison is not available yet.</strong><br>The map contains real satellite imagery, but quality-screened A/B extraction and paired differences are not connected. The regional curve below is not either area’s surface-temperature series.</div>':'<div class="notice"><strong>Regional climate context, not a local heat-island measurement.</strong><br>NASA POWER samples the grid near 1.3521° N, 103.8198° E. These values are not separate CBD and forest measurements.</div>')+'<div class="evidence-grid"><div class="panel"><div class="panel-header"><div><p class="label">SINGAPORE / 2001—2025</p><h3 id="chart-title">'+v.label+'</h3></div><label><span class="hidden">Variable</span><select id="variable" aria-label="Environmental variable">'+options()+'</select></label></div><p class="hint">Annual '+(state.variable==='PRECTOTCORR'?'total':'day-weighted mean')+' · '+v.unit+' · NASA POWER / '+esc(r.source_header.sources.join(', '))+'</p><div class="chart-wrap">'+chart(r,state.expanded)+'</div><div class="chart-key"><span>Observed annual values</span>'+(state.expanded?'<span class="fit">Estimated linear trend</span>':'')+'</div><p class="chart-hover" aria-live="polite">Select a point to inspect a year.</p><label class="field"><span>What do you notice? <small>· optional</small></span><textarea data-write="observation" placeholder="Before looking at statistics, describe a pattern or an unexpected year…">'+esc(state.observation)+'</textarea></label><button class="button ghost" data-action="statistics">'+(state.expanded?'Hide statistical evidence −':'Reveal statistical evidence +')+'</button><details style="margin-top:22px"><summary class="hint" style="cursor:pointer">Inspect all 25 annual values</summary><div class="table-scroll">'+dataTable(r)+'</div><button class="button ghost" data-action="csv" style="margin-top:15px">Download annual CSV ↓</button></details></div><aside><div class="panel"><p class="label">DATA AT A GLANCE</p><div class="stat"><small>Complete calendar years</small><strong>25 <span class="unit">of 25</span></strong></div><div class="stat"><small>2001 annual value</small><strong>'+fmt(r.annual[0].value)+'<span class="unit">'+v.unit+'</span></strong></div><div class="stat"><small>2025 annual value</small><strong>'+fmt(r.annual.at(-1).value)+'<span class="unit">'+v.unit+'</span></strong></div><div class="quality">No excluded years in this record</div><p class="hint">Retrieved '+esc(r.retrieved_at.slice(0,10))+'. Historical snapshot, not a live weather feed.</p><a class="hint" href="#sources">Understand the data ↗</a></div><div class="panel" style="margin-top:18px"><p class="label">A BETTER QUESTION</p><h3>Difference or trend?</h3><p class="hint">Being warmer and warming faster are different claims. A trend cannot, by itself, explain why change occurred.</p></div></aside></div>'+(state.expanded?'<div class="stats-block"><div class="stats-grid"><div class="panel"><h4>ESTIMATED CHANGE PER DECADE</h4><strong>'+fmt(s.slope_decade,3)+'</strong><p>'+v.unit+' per decade<br>Direction: '+esc(s.direction)+'</p></div><div class="panel"><h4>95% CONFIDENCE INTERVAL / DECADE</h4><strong style="font-size:23px">'+fmt(s.ci95_year[0]*10,3)+' to '+fmt(s.ci95_year[1]*10,3)+'</strong><p>'+v.unit+' per decade<br>HAC-adjusted, approximate t inference.</p></div><div class="panel"><h4>EVIDENCE AGAINST ZERO LINEAR SLOPE</h4><strong>'+ (s.significant?'Significant':'Inconclusive')+'</strong><p>p = '+Number(s.p_value).toPrecision(4)+' · threshold 0.05<br>'+(s.significant?'Evidence against a zero slope; not evidence of a cause.':'Not proof of no change.')+'</p></div></div><p class="hint">'+esc(s.method)+' Small samples, linear assumptions, grid resolution and repeated testing limit interpretation.</p><label class="check"><input id="reviewed" type="checkbox" '+(state.reviewed?'checked':'')+'>I have reviewed these regional observations, statistical evidence, and limitations.</label><a href="#notebook" class="button">Write my conclusion →</a></div>':'')+'</section>'}
function dataTable(r){return '<table><thead><tr><th>Year</th><th>Annual value ('+esc(V[state.variable].unit)+')</th></tr></thead><tbody>'+r.annual.map(p=>'<tr><td>'+p.year+'</td><td>'+fmt(p.value,4)+'</td></tr>').join('')+'</tbody></table>'}
function notebook(){const r=current(),v=V[state.variable],complete=state.mode==='regional'&&state.reviewed&&state.conclusion.trim();return pageHeading('03 / INTERPRET & REFLECT','The conclusion is yours.','Use the evidence. Keep your own voice. Revise when your understanding changes.',complete?'REGIONAL INVESTIGATION COMPLETE':'INVESTIGATION IN PROGRESS')+'<section class="container"><div class="notebook-grid"><div class="panel"><div class="panel-header"><h3>My investigation notebook</h3><span class="saved" id="save-state">Saved on this browser</span></div><label class="field"><span>Research question</span><textarea data-write="question" maxlength="2000">'+esc(state.question)+'</textarea></label><p class="hint">Focus: '+(state.mode==='regional'?'Singapore regional '+v.label.toLowerCase()+' · 2001–2025':esc(region(state.a).name)+' / '+esc(region(state.b).name)+' · area evidence incomplete')+'</p><div class="actions" style="margin:15px 0"><button class="button ghost" data-action="template">Insert writing prompts +</button><button class="button ghost" data-action="export-notes">Save notebook ↓</button></div><label class="field"><span>My conclusion</span><textarea class="note-area" data-write="conclusion" maxlength="12000" placeholder="What does the evidence support? What is still uncertain? Write your own conclusion here…">'+esc(state.conclusion)+'</textarea></label><p class="hint">Your writing stays yours. Guidance never replaces it. Changing the variable keeps your text and clears the reviewed-evidence flag.</p><div class="actions"><button class="button" data-action="print">Print / Save as PDF ↗</button><a class="button ghost" href="#evidence">Return to evidence</a></div><p class="hint">The browser print dialog lets you save a PDF. Incomplete investigations can also be exported and are labelled accordingly.</p></div><aside><div class="panel"><p class="label">YOUR EVIDENCE</p><h3>'+v.label+'</h3><p class="hint">Singapore regional series · '+v.unit+'<br>25 complete years · 2001–2025</p>'+chart(r,true)+'<p class="hint">Estimated change: '+fmt(r.stats.slope_decade,3)+' '+v.unit+' / decade.<br>This does not establish a cause.</p>'+(state.mode==='spatial'?'<div class="empty">A/B time series and differences are not yet available. Do not use this regional result as evidence of a local heat-island effect.</div>':'')+'</div><div class="panel" style="margin-top:20px"><p class="label">OPTIONAL WRITING SUPPORT</p><h3>A second look</h3><p class="hint">A transparent rule-based checklist, not an external AI model. It does not grade or rewrite your work.</p><button class="button ghost" data-action="feedback">Check my conclusion →</button><div id="feedback" class="feedback" aria-live="polite"></div></div></aside></div></section>'}
function sources(){return pageHeading('04 / DATA & METHODS','Know what sits beneath the map.','Real sources, visible processing choices, and honest limits.')+'<section class="container"><div class="source-grid"><article class="source-card"><span class="tag">LIVE · VIA CLIMATELENS SERVER</span><h3>NASA POWER</h3><p>Five annual regional series for Singapore, 2001–2025. Raw monthly observations were validated for units and all 12 months. Temperature, humidity, wind and solar energy use day-weighted means; precipitation sums daily rates × actual month lengths.</p><p>Meteorological grid data are not street-level air-temperature measurements. NASA source headers and URLs are preserved in every dataset file.</p><a href="'+esc(current().source_url)+'" target="_blank" rel="noopener">Open original POWER request ↗</a><br><a href="data/'+state.variable+'.json" download>Download verified result JSON ↓</a></article><article class="source-card"><span class="tag">CONNECTED · MAP IMAGERY</span><h3>MODIS through NASA GIBS</h3><p>Six historical 2024 Terra/MODIS daytime, 8-day composite images at 1 km product resolution. Their dates are sampled across the year; they are not monthly averages or a continuous animation. The official fixed legend is retained.</p><p>Transparent or missing retrievals remain empty. Rendered map colors are not quantitative A/B measurements and cannot replace quality-screened data extraction.</p><a href="'+esc(frames[state.frame].source)+'" target="_blank" rel="noopener">Open original GIBS image request ↗</a><br><a href="https://ladsweb.modaps.eosdis.nasa.gov/missions-and-measurements/products/MOD11A2/" target="_blank" rel="noopener">Read MOD11A2 product documentation ↗</a></article><article class="source-card"><span class="tag pending">NOT YET CONNECTED</span><h3>Local area comparison</h3><p>Map markers define proposed 1.5 km research areas. They are not confirmed urban or rural reference samples. AppEEARS extraction, pixel-quality filtering, paired valid dates, land-cover matching and A−B uncertainty must be added before a numerical heat-island conclusion.</p><p>NDVI, land cover and elevation measurements are not currently loaded. The illustrated map vegetation and buildings are decorative, not scientific layers.</p><a href="https://appeears.earthdatacloud.nasa.gov/" target="_blank" rel="noopener">Explore NASA AppEEARS ↗</a></article><article class="source-card"><span class="tag">REPRODUCIBLE REGIONAL ANALYSIS</span><h3>Statistics & interpretation</h3><p>'+esc(current().stats.method)+'</p><ul>'+current().stats.limitations.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul><p>Yearly slopes and confidence limits are multiplied by ten for decade units. A significant trend in one series and an inconclusive trend in another do not establish a significant difference between their trends.</p></article></div><div class="panel" style="margin-top:20px"><h3>Geography, privacy & provenance</h3><p class="hint">Singapore outline: Natural Earth via datasets/geo-countries (public-domain geographic data). Study-circle sizes are geographic approximations. The site stores your writing only in this browser; it has no account system or external AI service. The NASA POWER series are requested from the ClimateLens server (/api/investigate), which validates them and computes every statistic; the MODIS images and the outline are saved files. Download your work before clearing browser storage.</p><p class="hint">This independent prototype is not endorsed by NASA. It does not claim validated street-level microclimate, topographic cooling, or causal vegetation effects.</p><a class="button ghost" href="data/imagery.json" download>Download imagery provenance ↓</a></div></section>'}
function bindChart(){$$('.point').forEach(p=>{const inspect=()=>{const target=$('.chart-hover');if(target)target.textContent=p.dataset.year+' · '+fmt(p.dataset.value,3)+' '+V[state.variable].unit+' · observed annual value'};p.addEventListener('mouseenter',inspect);p.addEventListener('focus',inspect);p.addEventListener('click',inspect)})}
function updateMap(){const c=$('.map-canvas');if(c){const old=$('.map-svg',c);old.outerHTML=mapSVG();const credit=$('.map-credit',c);credit.textContent='Outline: Natural Earth · '+(state.layer==='heat'?'NASA GIBS MODIS · historical imagery':'Illustrative vegetation & buildings');const date=$('#frame-date');if(date)date.textContent=frames[state.frame].date}}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportReport(){const r=current(),v=V[state.variable],s=r.stats;const complete=state.mode==='regional'&&state.reviewed&&state.conclusion.trim();let el=$('.print-report');if(!el){el=document.createElement('article');el.className='print-report';document.body.append(el)}el.innerHTML='<h1>ClimateLens / Investigation report</h1><p><strong>'+ (state.mode==='spatial'?'Incomplete local evidence':complete?'Regional investigation completed':'Regional evidence available — review or conclusion incomplete')+'</strong></p><h2>Research question</h2><p>'+esc(state.question)+'</p><p>Singapore · '+esc(v.label)+' · 2001–2025 · '+esc(v.unit)+'</p><p>Proposed areas: '+esc(region(state.a).name)+' and '+esc(region(state.b).name)+'. Numerical area extraction is not connected.</p><h2>Prediction / observation</h2><p>'+esc(state.hypothesis||'Prediction skipped')+'</p><p>'+esc(state.observation||'No observation notes')+'</p><h2>Verified regional evidence</h2>'+chart(r,true)+'<p>Estimated slope: '+fmt(s.slope_decade,4)+' '+esc(v.unit)+' per decade. 95% confidence interval: ['+fmt(s.ci95_year[0]*10,4)+', '+fmt(s.ci95_year[1]*10,4)+']. p = '+esc(Number(s.p_value).toPrecision(5))+'. '+esc(s.method)+'</p><h2>Student-authored conclusion</h2><p>'+esc(state.conclusion||'Not yet written')+'</p><h2>Sources and limitations</h2><p>NASA POWER regional grid near 1.3521° N, 103.8198° E. Retrieved '+esc(r.retrieved_at)+'. '+esc(r.aggregation)+'. Excluded years: '+esc(JSON.stringify(r.excluded_years))+'.</p><p>'+esc(r.source_url)+'</p><p>'+esc(s.limitations.join('\n'))+'</p><p>Local A/B observations, NDVI and terrain have not been extracted. The regional time series cannot establish an urban heat-island difference or causal explanation.</p><p>Map imagery: NASA GIBS / MODIS Terra daytime 8-day composite. Displayed date '+frames[state.frame].date+'. Imagery is not used to calculate regional statistics.</p><p>'+esc(frames[state.frame].source)+'</p><h2>Annual observations</h2>'+dataTable(r);window.print()}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action],[data-region],[data-slot],[data-layer],[data-mode],[data-example]');if(!el)return;if(el.dataset.region){const key=state.slot,other=key==='a'?'b':'a';if(state[other]===el.dataset.region){toast('Choose a different area for A and B.');return}state[key]=el.dataset.region;state.reviewed=false;persist();main.innerHTML=explore();return}if(el.dataset.slot){state.slot=el.dataset.slot;main.innerHTML=explore();return}if(el.dataset.layer){state.layer=el.dataset.layer;persist();main.innerHTML=explore();return}if(el.dataset.mode){state.mode=el.dataset.mode;state.reviewed=false;state.expanded=false;persist();main.innerHTML=evidence();bindChart();return}if(el.dataset.example){state.mode='regional';persist();return}switch(el.dataset.action){case'swap':[state.a,state.b]=[state.b,state.a];state.reviewed=false;persist();main.innerHTML=explore();break;case'zoom-in':state.zoom=Math.min(2.2,state.zoom+.3);updateMap();break;case'zoom-out':state.zoom=Math.max(.7,state.zoom-.3);updateMap();break;case'reset-map':state.zoom=1;updateMap();break;case'play':if(timer){clearInterval(timer);timer=null;el.textContent='▶';el.setAttribute('aria-label','Play historical imagery')}else{state.layer='heat';main.innerHTML=explore();const play=$('[data-action="play"]');play.textContent='Ⅱ';play.setAttribute('aria-label','Pause historical imagery');timer=setInterval(()=>{state.frame=(state.frame+1)%frames.length;$('#frame').value=state.frame;updateMap()},1500)}break;case'statistics':state.expanded=!state.expanded;main.innerHTML=evidence();bindChart();break;case'csv':download('ClimateLens-Singapore-'+state.variable+'.csv','year,value,unit\n'+current().annual.map(r=>[r.year,r.value,V[state.variable].unit].join(',')).join('\n'),'text/csv;charset=utf-8');break;case'template':{const area=$('[data-write="conclusion"]');const prompts='\n\nMy evidence: …\nMy interpretation: …\nWhat remains uncertain: …\nA useful next investigation would be: …';state.conclusion+=prompts;area.value=state.conclusion;persist();area.focus();toast('Prompts appended. Your existing writing was kept.');break}case'feedback':{const text=state.conclusion.trim();const tips=[];if(!text)tips.push('Start with your own observation or interpretation. You can still export an incomplete report.');else{tips.push('Check every numerical claim against the '+V[state.variable].label.toLowerCase()+' evidence. Estimated regional change is '+fmt(current().stats.slope_decade,3)+' '+V[state.variable].unit+' per decade.');if(/caus|prove|because|导致|证明|调节/i.test(text))tips.push('Review causal wording. These observations alone do not show that vegetation or buildings caused the change.');else tips.push('State the uncertainty and the regional grid scale. A trend is not a causal explanation.');if(state.mode==='spatial')tips.push('Your local comparison has incomplete evidence. Do not claim a measured A/B temperature difference.')}$('#feedback').innerHTML='<strong>Suggestions — your writing is unchanged</strong><ul>'+tips.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul>';break}case'export-notes':download('ClimateLens-notebook.json',JSON.stringify({saved_at:new Date().toISOString(),...state,source:current().source_url},null,2),'application/json');break;case'print':exportReport();break}});
document.addEventListener('keydown',e=>{const el=e.target.closest('[data-region]');if(el&&(e.key==='Enter'||e.key===' ')){e.preventDefault();el.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.write){state[el.dataset.write]=el.value;if(el.dataset.write==='question')state.reviewed=false;persist();const s=$('#save-state');if(s)s.textContent='Saved on this browser'}if(el.id==='frame'){state.frame=Number(el.value);persist();updateMap()}});
document.addEventListener('change',e=>{if(e.target.id==='variable'){state.variable=e.target.value;state.reviewed=false;state.expanded=false;persist();main.innerHTML=evidence();bindChart();toast('Variable changed. Your writing is kept; review the new evidence.')}if(e.target.id==='reviewed'){state.reviewed=e.target.checked;persist()}});
window.addEventListener('hashchange',navigate);document.addEventListener('visibilitychange',()=>{if(document.hidden&&timer){clearInterval(timer);timer=null;const b=$('[data-action="play"]');if(b)b.textContent='▶'}});
async function init(){main.innerHTML='<div class="loading">Finding our place on the island…</div>';try{const files=await Promise.all(['data/singapore.geojson','data/imagery.json',...Object.keys(V).map(v=>'data/'+v+'.json')].map(async u=>{const r=await offlineFetch(u);if(!r.ok)throw new Error('Could not load '+u);return r.json()}));geo=files[0];frames=files[1];Object.keys(V).forEach((v,i)=>data[v]=files[i+2]);ready=true;navigate()}catch(e){main.innerHTML='<section class="error"><h1>The data could not be loaded.</h1><p>'+esc(e.message)+'</p><p>Check your connection and reload. No replacement data have been generated.</p><button class="button" id="retry">Try again</button></section>';$('#retry').onclick=init}}
// Optional background music: the Singapore track from the five-island page. Muted by default; the choice is shared with that page.
var labSound=null;
try{let store;try{store=window.localStorage}catch(e){store={getItem:()=>null,setItem:()=>{}}}
 labSound=Soundscape.createPlayer(document,store);
 labSound.mount({root:$('#sound'),toggle:$('#soundToggle'),state:$('#soundState'),title:$('#soundTitle'),volume:$('#soundVolume'),pct:$('#soundPct'),offer:$('#soundOffer'),offerOn:$('#soundOfferOn'),offerNo:$('#soundOfferNo')});
}catch(e){const el=document.getElementById('sound');if(el)el.hidden=true}  // music is optional: any failure leaves the lab untouched
init();
